package taxonomy.runner

import kotlinx.serialization.json.Json
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import taxonomy.dataset.ReservedPool
import java.io.File

/**
 * INTENT-TRANSFER-S1 (docs/judge_v2_program.md L22682-L22710): the nine committed arm configs experiment_configs/intent_s1/<slug>.toml
 * (generated by tools/analysis/intent_s1_export.py --write-configs) parse through the production TOML parser (unknown keys fatal)
 * and the INTENT cross-check, carry the registered recipe per arm, and their `pool` equals ReservedPool.computePoolId of the
 * committed GATE export they name (the Kotlin half of the pool-id mirror, on the real exports). Same Spring context as
 * LcbStage0ConfigTest.
 */
@SpringBootTest(
    classes = [taxonomy.TaxoAdaptApplication::class],
    properties = [
        "taxoadapt.execution.enable-tui=false",
        "taxoadapt.execution.run-batch=false",
        "taxoadapt.execution.start-service=false",
        "taxoadapt.llm.judge-model=qwen3.6:27b",
        "taxoadapt.llm.labeling-model=gemma4:e4b"
    ]
)
class IntentS1ConfigTest {

    @Autowired
    lateinit var runner: HeadlessBenchmarkRunner

    private val dir = File("experiment_configs/intent_s1")

    // slug -> (corpus, salt, anchored, slice, shuffle seed)
    private val arms = linkedMapOf(
        "m_af" to listOf("massive", 1, false, null, null),
        "m_af_replay" to listOf("massive", 1, false, null, null),
        "m_o1" to listOf("massive", 1, false, null, 1L),
        "m_o2" to listOf("massive", 1, false, null, 2L),
        "m_af_s2" to listOf("massive", 2, false, null, null),
        "m_an" to listOf("massive", 1, true, 512, null),
        "c_af" to listOf("clinc", 1, false, null, null),
        "c_an" to listOf("clinc", 1, true, 512, null),
        "m_af_g" to listOf("massive", 1, false, 768, null),
    )

    @Test
    fun `the nine arm configs parse and carry the registered recipe`() {
        assertTrue(dir.isDirectory, "${dir.path} not found; run from the repo root")
        assertEquals(arms.keys.map { "$it.toml" }.toSet(), dir.listFiles()!!.filter { it.name.endsWith(".toml") }.map { it.name }.toSet())
        val pools = HashMap<String, String>()
        for ((slug, spec) in arms) {
            val (corpus, salt, anchored, slice, shuffle) = spec
            val c = runner.parseToml(File(dir, "$slug.toml").readText())
            assertEquals("INTENT", c.datasetType, slug)
            assertEquals("intent_s1_build/$slug.db", c.corpusDbPath, slug)
            assertEquals("experiment_results/intent_transfer/s1/$slug", c.outputDir, slug)
            assertEquals("experiment_configs/intent_s1/gate_ids_${corpus}_s$salt.json", c.reservedPoolFile, slug)
            assertTrue(c.runPipeline && c.runTrickle && !c.runBenchmark && !c.judgeInduction && !c.runBaselines, slug)
            assertEquals(false, c.enableLabeling, slug)
            assertEquals(false, c.enableFinalMetrics, slug)
            assertTrue(c.models.isEmpty() && c.seeds.isEmpty(), "$slug: models = [] and never `seeds = [...]`")
            assertNull(c.corpora, slug)
            assertEquals(anchored == false, c.anchorFree, slug)
            assertEquals(slice as Int?, c.embeddingSliceDim, slug)
            assertEquals(if (anchored == true) 0.0145 else 0.025, c.proposalSeparationBar!!, 0.0, slug)
            assertEquals(shuffle as Long?, c.constructionOrderShuffleSeed, slug)
            assertEquals(55, c.minClusterSize, slug)
            assertEquals(2.0, c.acceptanceZ!!, 0.0, slug)
            assertEquals(50, c.numIterations, slug)
            assertEquals(8, c.maxDepth, slug)
            assertEquals(42L, c.seed, slug)
            if (anchored == true) {
                assertEquals(0, c.splitDropTopPcs, slug)
                assertEquals(false, c.splitWhiten, slug)
            }
            // the [POOL-PIN] equals the Kotlin pool id of the GATE export the config names
            val ids: Map<String, List<Int>> = Json.decodeFromString(File(c.reservedPoolFile!!).readText())
            assertTrue(ids.values.flatten().all { it in 11_000_001..11_999_999 }, "$slug: GATE ids in the INTENT namespace")
            assertEquals(ReservedPool.computePoolId(ids), c.pool, slug)
            pools[slug] = c.pool!!
        }
        // same-input arms share the pool; the salt-2 re-draw and CLINC have their own
        assertEquals(setOf(pools["m_af"]), arms.keys.filter { arms[it]!![0] == "massive" && arms[it]!![1] == 1 }.map { pools[it] }.toSet())
        assertTrue(pools["m_af_s2"] != pools["m_af"] && pools["c_af"] == pools["c_an"] && pools["c_af"] != pools["m_af"])
    }
}
